<template> <ion-page> <ion-header> <ion-toolbar> <ion-buttons slot="start"> <ion-back-button default-href="/settings"></ion-back-button> </ion-buttons> <ion-title>Blockchain Settings</ion-title> </ion-toolbar> </ion-header> <ion-content :fullscreen="true"> <ion-list> <ion-item> <ion-label>Network</ion-label> <ion-select v-model="blockchain.network" @ionChange="updateBlockchain"> <ion-select-option value="mainnet">Mainnet</ion-select-option> <ion-select-option value="testnet">Testnet</ion-select-option> </ion-select> </ion-item> <ion-item> <ion-label position="stacked">Custom RPC URL</ion-label> <ion-input v-model="blockchain.customRpc" @ionInput="updateBlockchain"></ion-input> </ion-item> </ion-list> <ion-toast :is-open="toast.isOpen" :message="toast.message" :duration="2000" @didDismiss="toast.isOpen = false" ></ion-toast> </ion-content> </ion-page> </template> <script lang="ts"> import { defineComponent, ref, onMounted } from 'vue'; import { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonSelect, IonSelectOption, IonInput, IonToast, } from '@ionic/vue'; import api from '../services/api'; import { BlockchainSettings } from '../types/settings'; export default defineComponent({ name: 'BlockchainSettings', components: { IonPage, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonContent, IonList, IonItem, IonLabel, IonSelect, IonSelectOption, IonInput, IonToast }, setup() { const blockchain = ref<BlockchainSettings>({ network: 'mainnet', customRpc: '' }); const toast = ref({ isOpen: false, message: '' }); const fetchBlockchain = async () => { try { const response = await api.get('/user/blockchain'); blockchain.value = response.data; } catch (error) { toast.value = { isOpen: true, message: 'Failed to load blockchain settings' }; } }; const updateBlockchain = async () => { try { await api.post('/user/blockchain', blockchain.value); toast.value = { isOpen: true, message: 'Blockchain settings updated' }; } catch (error) { toast.value = { isOpen: true, message: 'Failed to update blockchain settings' }; } }; onMounted(fetchBlockchain); return { blockchain, toast, updateBlockchain }; }, }); </script>